import { mermaidLabel } from './mermaid-label.js';

// RF-262, RF-508, DEC-134: the Mermaid entity-relationship diagram of the legacy data model,
// generated by code from the entities of the ENT cards; the model never writes Mermaid. Entities
// are drawn in card id order; a relation to an entity without a card gets one entity of its own.
// A cardinality the cards do not state is never guessed: that end is drawn open (zero or more),
// the line dotted, and the label says "cardinality unknown". Entity and field ids are generated
// (`e1`, `f1`, ...), never taken from the code: a field's name and type travel only in its
// quoted comment. Every label goes through `mermaidLabel`.

export type Cardinality = 'one' | 'zero-or-one' | 'zero-or-more' | 'one-or-more' | 'unknown';
export type FieldKey = 'PK' | 'FK' | 'UK';

interface ModelField {
  readonly name: string;
  readonly type?: string | undefined;
  readonly keys?: readonly FieldKey[] | undefined;
}

/** One entity of the data model: the ENT card it comes from, its name and its fields. */
interface ModelEntity {
  readonly cardId: string;
  readonly name: string;
  readonly fields: readonly ModelField[];
}

/** `from` and `to` are ENT card ids; each cardinality is how many of that end take part. */
interface ModelRelation {
  readonly from: string;
  readonly to: string;
  readonly label: string;
  readonly fromCardinality: Cardinality;
  readonly toCardinality: Cardinality;
}

export interface EntityModel {
  readonly entities: readonly ModelEntity[];
  readonly relations: readonly ModelRelation[];
}

const leftEnd: Readonly<Record<Cardinality, string>> = {
  one: '||',
  'zero-or-one': '|o',
  'zero-or-more': '}o',
  'one-or-more': '}|',
  unknown: '}o',
};

const rightEnd: Readonly<Record<Cardinality, string>> = {
  one: '||',
  'zero-or-one': 'o|',
  'zero-or-more': 'o{',
  'one-or-more': '|{',
  unknown: 'o{',
};

function fieldLine(field: ModelField, index: number): string {
  const keys =
    field.keys === undefined || field.keys.length === 0 ? '' : ` ${field.keys.join(', ')}`;
  const text = field.type === undefined ? field.name : `${field.name}: ${field.type}`;
  return `    field f${String(index + 1)}${keys} "${mermaidLabel(text)}"`;
}

function entityLines(id: string, entity: ModelEntity): readonly string[] {
  const head = `  ${id}["${mermaidLabel(entity.name)}"]`;
  if (entity.fields.length === 0) return [head];
  return [`${head} {`, ...entity.fields.map(fieldLine), '  }'];
}

function relationLine(relation: ModelRelation, from: string, to: string): string {
  const unknown = relation.fromCardinality === 'unknown' || relation.toCardinality === 'unknown';
  const line = unknown ? '..' : '--';
  const label = unknown ? `${relation.label} (cardinality unknown)` : relation.label;
  const ends = `${leftEnd[relation.fromCardinality]}${line}${rightEnd[relation.toCardinality]}`;
  return `  ${from} ${ends} ${to} : "${mermaidLabel(label)}"`;
}

function byCardId(left: ModelEntity, right: ModelEntity): number {
  if (left.cardId === right.cardId) return 0;
  return left.cardId < right.cardId ? -1 : 1;
}

// RF-262
export function entityDiagram(model: EntityModel): string {
  const idOf = new Map<string, string>();
  const entities: string[] = [];
  const place = (entity: ModelEntity): string => {
    const known = idOf.get(entity.cardId);
    if (known !== undefined) return known;
    const id = `e${String(idOf.size + 1)}`;
    idOf.set(entity.cardId, id);
    entities.push(...entityLines(id, entity));
    return id;
  };
  model.entities.toSorted(byCardId).forEach(place);
  const endOf = (cardId: string): string => place({ cardId, name: cardId, fields: [] });
  const relations = model.relations.map((relation) =>
    relationLine(relation, endOf(relation.from), endOf(relation.to)),
  );
  return ['erDiagram', ...entities, ...relations, ''].join('\n');
}
